    expect(render(" a \n{{! ignored }}\n b ", {})).toBe(" a \n\n b ");
  });

  test("rejects nonscalar interpolation", () => {
    expect(() => render("line\n{{value}}", { value: {} })).toThrow("line 2, column 1");
    expect(() => render("{{value}}", { value: {} })).toThrow("not scalar");
  });

