    const cases = [
      ["x\n{{else}}", "else outside a block at line 2, column 1"],
      ["{{#if x}}{{else}}{{else}}{{/if}}", "Duplicate else"],
      ["{{#if x}}{{/each}}", "Mismatched close"],
      ["{{#wat x}}", "Unknown or malformed block"],
      ["{{#each x}}", "Unclosed each block"],
